from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: 'Expr'
    r: 'Expr'


@dataclass
class Mul:
    l: 'Expr'
    r: 'Expr'


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an arithmetic expression tree.

    Num evaluates to its value, Add to the sum of its operands' values,
    and Mul to the product of its operands' values.
    """
    match e:
        case Num(v):
            return v
        case Add(l, r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l, r):
            return eval_expr(l) * eval_expr(r)


def test_num() -> None:
    assert eval_expr(Num(7)) == 7
    assert eval_expr(Num(0)) == 0
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5
    assert eval_expr(Add(Num(-2), Num(2))) == 0


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20
    assert eval_expr(Mul(Num(-4), Num(5))) == -20
    assert eval_expr(Mul(Num(0), Num(99))) == 0


def test_nested() -> None:
    # (2 + 3) * (4 + 1) = 25
    e = Mul(Add(Num(2), Num(3)), Add(Num(4), Num(1)))
    assert eval_expr(e) == 25
    # 2 + (3 * 4) = 14
    assert eval_expr(Add(Num(2), Mul(Num(3), Num(4)))) == 14
    # (1 + 2) * 3 + 4 * (5 + 6) = 9 + 44 = 53
    e2 = Add(
        Mul(Add(Num(1), Num(2)), Num(3)),
        Mul(Num(4), Add(Num(5), Num(6))),
    )
    assert eval_expr(e2) == 53


def test_identities() -> None:
    assert eval_expr(Add(Num(9), Num(0))) == 9
    assert eval_expr(Mul(Num(9), Num(1))) == 9


def test_large_values() -> None:
    big = 10**18
    assert eval_expr(Mul(Num(big), Num(big))) == big * big


def test_deep_left_chain() -> None:
    e: Expr = Num(0)
    for i in range(1, 201):
        e = Add(e, Num(i))
    assert eval_expr(e) == sum(range(1, 201))


def test_does_not_mutate() -> None:
    e = Add(Num(1), Mul(Num(2), Num(3)))
    eval_expr(e)
    assert e == Add(Num(1), Mul(Num(2), Num(3)))

